var organizeFiles = (files) => {
	const items = [];
	if (!files) return [];
	files.forEach((item) => {
		if (!item?.multipart) {
			items.push(item);
			return;
		}
		if (item.upload.part === 1) items.push({
			...item,
			upload: {
				...item.upload,
				size: item.totalSize
			}
		});
	});
	return items;
};
